@Override
public void appendCommitRecord(final long txID,
                               final boolean sync,
                               final IOCompletion callback,
                               final boolean lineUpContext) throws Exception {
   checkJournalIsLoaded();
   if (lineUpContext) {
      lineUpContext(callback);
   }

   final JournalTransaction tx = transactions.remove(txID);

   if (tx == null) {
      throw new IllegalStateException("Cannot find tx with id " + txID);
   }

   tx.checkErrorCondition();
   final SimpleFuture<Boolean> result = newSyncAndCallbackResult(sync, callback);

   appendExecutor.execute(new Runnable() {
      @Override
      public void run() {
         journalLock.readLock().lock();
         try {
            JournalInternalRecord commitRecord = new JournalCompleteRecordTX(TX_RECORD_TYPE.COMMIT, txID, null);
            JournalFile usedFile = appendRecord(commitRecord, true, sync, tx, callback);


            if (logger.isTraceEnabled()) {
               logger.trace("appendCommitRecord::txID=" + txID + ", usedFile = " + usedFile);
            }

            tx.commit(usedFile);
            if (result != null) {
               result.set(true);
            }
         } catch (Exception e) {
            if (result != null) {
               result.fail(e);
            }
            logger.error("appendCommitRecord:" + e, e);
            setErrorCondition(tx, e);
         } finally {
            journalLock.readLock().unlock();
         }
      }
   });

   if (result != null) {
      result.get();
      tx.checkErrorCondition();
   }
}

@Override
public void appendRollbackRecord(final long txID, final boolean sync, final IOCompletion callback) throws Exception {
   checkJournalIsLoaded();
   lineUpContext(callback);

   final JournalTransaction tx = transactions.remove(txID);

   if (tx == null) {
      throw new IllegalStateException("Cannot find tx with id " + txID);
   }

   tx.checkErrorCondition();
   final SimpleFuture<Boolean> result = newSyncAndCallbackResult(sync, callback);
   appendExecutor.execute(new Runnable() {
      @Override
      public void run() {
         journalLock.readLock().lock();
         try {
            JournalInternalRecord rollbackRecord = new JournalRollbackRecordTX(txID);
            JournalFile usedFile = appendRecord(rollbackRecord, false, sync, tx, callback);

            tx.rollback(usedFile);
            if (result != null) {
               result.set(true);
            }
         } catch (Exception e) {
            if (result != null) {
               result.fail(e);
            }
            logger.error("appendRollbackRecord:" + e, e);
            setErrorCondition(tx, e);
         }  finally {
            journalLock.readLock().unlock();
         }
      }
   });

   if (result != null) {
      result.get();
      tx.checkErrorCondition();
   }
}

